SELECT
  json_extract(value, '$.group') AS "group",
  json_extract(value, '$.observed') AS "observed",
  json_extract(value, '$.meaning') AS "meaning"
FROM json_each('[{"group": "15 other main deployments", "observed": "3/3 automated and the required answer facts were present", "meaning": "The chosen route supported the tested text/tool workflow; this does not validate every feature."}, {"group": "Cohere-parse-v5", "observed": "404 api_not_supported on the chat route", "meaning": "A parsing model needs the appropriate task-specific integration."}, {"group": "DeepSeek-V4-Flash-0731", "observed": "Some replies and one correct sample, then 180-second request timeouts; eval failed with 408", "meaning": "Protocol compatibility and deployment reliability are separate."}, {"group": "FLUX.2-pro", "observed": "404 on the chat route", "meaning": "Image generation needs an image/vendor adapter."}, {"group": "GPT-4o", "observed": "Automated 3/3; required-fact review 2/3 because taxi was omitted", "meaning": "The grader accepted an incomplete answer; transport success did not prove task success."}, {"group": "Ministral-3B", "observed": "429 after retries even with one sample at a time; missing-file sample succeeded", "meaning": "The provider honored waits but could not remove a capacity constraint."}, {"group": "gpt-5.4-pro", "observed": "400 unsupported operation on the legacy chat route", "meaning": "Check a supported API such as Responses rather than treating the model as universally unusable."}]');
